<?php
require_once __DIR__ . '/blocks.php';
function sy3_home_content(): string {
    $contact = 'https://t.me/sy3_support_bot?start=site_sy3';
    $hero = sy3_p('СУТРИ / ЦИФРОВЫЕ РЕШЕНИЯ ДЛЯ БИЗНЕСА', 'eyebrow hero-kicker') .
        sy3_h('Сайты, сервисы<br>и автоматизация.<br><em>С фокусом на бизнес.</em>', 1) .
        sy3_cols([
            sy3_g(
                sy3_image('artem-suyazov.jpg', 'Артём Суязов — основатель Сутри.', 'hero-portrait') .
                sy3_g(sy3_p('Артём Суязов', 'portrait-name') . sy3_p('Ваш IT-бизнес-партнёр.<br>Лично веду проект от задачи до запуска.', 'portrait-role') . sy3_p('<a href="' . esc_url(home_url('/about/')) . '">Познакомиться</a>', 'portrait-link'), 'hero-person-copy'),
                'hero-person'
            ),
            sy3_p('Разрабатываем сайты и веб-сервисы, внедряем CRM, связываем системы и данные. Чтобы клиентам было удобно обратиться, а команде — принять заявку и выполнить работу.', 'hero-intro') .
            sy3_buttons([['Обсудить проект', $contact], ['Посмотреть работы', '#selected-cases', true]]) .
            sy3_p('Можно начать с одной задачи. Границы, стоимость и способ проверки согласуем до работы.', 'hero-note')
        ], 'hero-bottom') .
        sy3_g(
            sy3_p('<strong>Битрикс24</strong><br>Бизнес-партнёр') .
            sy3_p('<strong>25 кейсов</strong><br>Задачи и выполненная работа') .
            sy3_p('<strong>От сайта до данных</strong><br>Один понятный процесс') .
            sy3_p('<strong>Личный контакт</strong><br>Проект ведёт Артём'),
            'trust-strip'
        );
    $cases = sy3_p('01 / Работа в деталях', 'eyebrow') . sy3_g(sy3_h('<span id="selected-cases">Реальные задачи.<br>Работающие решения.</span>') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/cases/')) . '">Все 25 кейсов</a>'), 'section-heading') . sy3_shortcode('[sy3_featured_cases]');
    $services = sy3_p('02 / Что делаем', 'eyebrow') . sy3_g(sy3_h('От первого экрана<br>до данных бизнеса.') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/services/')) . '">Все направления</a>'), 'section-heading') .
        sy3_p('Сайт, CRM, учёт и аналитика должны помогать одному процессу. Подбираем состав работ под вашу задачу, а не под набор инструментов.', 'section-intro') .
        sy3_shortcode('[sy3_core_services]') .
        sy3_p('Для задач по 1С и BI подключаем профильных специалистов. Артём отвечает за постановку задачи, координацию и проверку общего результата.', 'delivery-note');
    $process = sy3_p('03 / Как работаем', 'eyebrow') . sy3_h('Сначала — понять.<br>Потом — разработать.') . sy3_p('У каждого этапа есть задача, результат и понятный способ приёмки.', 'section-intro') . sy3_cols([
        sy3_p('01 / РАЗОБРАТЬСЯ', 'step-number') . sy3_h('Увидеть процесс', 3) . sy3_p('Разбираем путь клиента, участников и системы. Находим, где теряется заявка, время или информация.'),
        sy3_p('02 / СПРОЕКТИРОВАТЬ', 'step-number') . sy3_h('Выбрать решение', 3) . sy3_p('Согласуем первый этап: состав работ, стоимость, ограничения и сценарий проверки.'),
        sy3_p('03 / СДЕЛАТЬ', 'step-number') . sy3_h('Собрать и связать', 3) . sy3_p('Разрабатываем сайт или сервис, настраиваем CRM и обмен данными. Для ИИ начинаем с ограниченного пилота.'),
        sy3_p('04 / ПРОВЕРИТЬ', 'step-number') . sy3_h('Довести до работы', 3) . sy3_p('Вместе проходим рабочий сценарий. Передаём инструкции и договариваемся о дальнейшем развитии.')
    ], 'process-grid');
    $author = sy3_cols([
        sy3_image('artem-suyazov.jpg', 'Артём Суязов.', 'author-portrait') . sy3_p('Артём Суязов<br><span>IT-бизнес-партнёр · основатель Сутри</span>', 'author-name'),
        sy3_p('04 / Кто отвечает за работу', 'eyebrow') . sy3_h('С вами работает<br>конкретный человек.') .
        sy3_p('Привет, я Артём. Лично разбираю вашу задачу, предлагаю решение и согласовываю результат. Вы знаете, кому задать вопрос и с кем обсудить следующий шаг.') .
        sy3_p('В портфолио — сайты, сервисы и автоматизация для торговли, образования и сервисного бизнеса. В каждом кейсе описаны задача, выполненная работа и границы подтверждённого результата.') .
        sy3_p('Если проекту нужны специалисты по 1С или аналитике данных, собираю участников вокруг общей задачи. Постановка, координация и приёмка остаются в одном контуре.') .
        sy3_buttons([['Написать Артёму', $contact]]) . sy3_p('<a class="text-link" href="' . esc_url(home_url('/about/')) . '">Обо мне и подходе</a>')
    ], 'author-grid');
    $journal = sy3_p('05 / Практика и знания', 'eyebrow') . sy3_g(sy3_h('Понимать технологии.<br>Принимать решения.') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/journal/')) . '">Читать журнал</a>'), 'section-heading') . sy3_p('Разборы для собственника и команды: что проверить, с чего начать и как принять работу.', 'section-intro') . sy3_shortcode('[sy3_cards type="post" count="3"]');
    $faq = sy3_p('06 / До начала работы', 'eyebrow') . sy3_h('Вопросы по делу') . sy3_g(
        sy3_faq('Можно начать с небольшой задачи?', 'Да. Например, проверить путь заявки с сайта до CRM, исправить интеграцию или разобрать один бизнес-процесс. У первого этапа будут конкретные границы и критерий готовности.') .
        sy3_faq('У нас уже есть сайт и CRM. Нужно всё менять?', 'Сначала разбираем текущую систему. Часто можно исправить отдельный участок: форму, передачу заявки, обмен данными или работу менеджеров. Замену обсуждаем при понятных причинах.') .
        sy3_faq('Сколько стоит проект?', 'После разбора задачи согласуем состав первого этапа и стоимость. Цена зависит от процессов, интеграций, состояния данных и объёма разработки. Лицензии и платные сервисы обсуждаем отдельно.') .
        sy3_faq('Кто будет работать над задачами по 1С и аналитике?', 'Подключаем профильных подрядчиков по 1С и специалистов по аналитике данных. Артём ведёт постановку задачи, согласование участников и проверку решения в общем процессе.'), 'faq-list');
    $cta = sy3_cols([
        sy3_p('Начнём с вашей задачи', 'eyebrow') . sy3_h('Есть задача?<br><em>Давайте разберёмся.</em>'),
        sy3_p('Расскажите, что хотите запустить или улучшить. Обсудим, с чего начать, какой результат нужен и как его проверить.') . sy3_buttons([['Обсудить проект с Артёмом', $contact]]) . sy3_p('<a href="https://max.ru/id263514840335_1_bot?start=site_sy3">Написать в MAX</a>', 'contact-alternative')
    ], 'cta-panel');
    return sy3_g(sy3_g($hero, 'section-inner'), 'hero hero-redesign hero-editorial', 'section') . sy3_section($cases, 'work-section') . sy3_section($services, 'services-section') . sy3_section($process, 'section-dark') . sy3_section($author, 'author-section') . sy3_section($journal, 'journal-section') . sy3_section($faq) . sy3_section($cta, 'contact-section');
}

function sy3_personal_home(): string {
    $main = rtrim(get_option('sy3_main_url', 'https://sy3.ru'), '/');
    $hero = sy3_g(sy3_cols([
        sy3_p('Артём Суязов / IT-бизнес-партнёр', 'eyebrow') . sy3_h('На стороне<br>бизнеса.<br><em>На языке IT.</em>', 1) . sy3_p('Разбираюсь в процессах, связываю системы и довожу решения до работы. CRM, интеграции и ИИ — с понятной целью.', 'hero-intro') . sy3_buttons([['Обсудить сотрудничество ↗', home_url('/contacts/')], ['Мои работы ↗', home_url('/portfolio/'), true]]) . sy3_p('Проектные задачи и постоянное участие в развитии IT.', 'hero-note'),
        sy3_shortcode('[sy3_visual mode="personal"]')
    ], 'hero-columns'), 'section-inner');
    $scope = sy3_p('01 / Чем могу быть полезен', 'eyebrow') . sy3_h('Связать задачу бизнеса<br>с работающим решением.') . sy3_cols([
        sy3_h('Разобраться', 3) . sy3_p('Собрать картину текущих систем и процессов. Понять, почему работа буксует и что менять первым.'),
        sy3_h('Довести до работы', 3) . sy3_p('Согласовать первый этап, собрать решение и проверить полный сценарий вместе с командой.'),
        sy3_h('Развивать дальше', 3) . sy3_p('Поддерживать систему, разбирать новые задачи и сохранять понятную документацию решений.')
    ], 'problem-grid');
    $works = sy3_p('02 / Выбранные работы', 'eyebrow') . sy3_h('Опыт — в деталях проектов.') . sy3_p('Подробные кейсы собраны на основном сайте Сутри: там описаны задача, работа и границы подтверждённого результата.', 'section-intro') . sy3_shortcode('[sy3_external_cases]');
    $approach = sy3_p('03 / Мой подход', 'eyebrow') . sy3_h('Понятность —<br>часть результата.') . sy3_p('В работе мне важны три вопроса: какую проблему решаем, кто будет пользоваться решением и как мы поймём, что задача выполнена.', 'section-intro') . sy3_cols([
        sy3_p('01', 'step-number') . sy3_h('Задача раньше инструмента', 3) . sy3_p('Сначала процесс и ограничения. Затем выбор CRM, интеграции или ИИ.'),
        sy3_p('02', 'step-number') . sy3_h('У первого этапа есть границы', 3) . sy3_p('Согласуем объём, критерии готовности и вопросы, которые остаются за рамками.'),
        sy3_p('03', 'step-number') . sy3_h('Проверка на вашем сценарии', 3) . sy3_p('Проверяем путь пользователя, а не только отдельную настройку.'),
        sy3_p('04', 'step-number') . sy3_h('Знания остаются у команды', 3) . sy3_p('Передаём инструкции, решения и понятный следующий шаг.')
    ], 'process-grid');
    $links = sy3_p('04 / Услуги и материалы', 'eyebrow') . sy3_h('Больше практики — на Сутри.') . sy3_p('Подробные направления работы, кейсы и экспертный журнал находятся на одном основном сайте. Здесь — мой подход и возможность обсудить сотрудничество.', 'section-intro') . sy3_buttons([['Услуги и кейсы ↗', $main . '/'], ['Читать журнал ↗', $main . '/journal/', true]]);
    $cta = sy3_cols([sy3_h('Нужен человек,<br>который разберётся?'), sy3_p('Расскажите о бизнесе, текущих системах и задаче. Обсудим, какой формат работы подойдёт.') . sy3_buttons([['Написать Артёму ↗', home_url('/contacts/')]])], 'cta-panel');
    return sy3_g($hero, 'hero', 'section') . sy3_section($scope) . sy3_section($works, 'section-tint') . sy3_section($approach, 'section-dark') . sy3_section($links) . sy3_section($cta);
}
